package main; import ("fmt"; "net/http"; "time"); func main() { t0 := time.Now(); resp, err := http.Post("http://127.0.0.1:11434/api/tags", "application/json", nil); fmt.Println("127.0.0.1:", time.Since(t0), err); if resp != nil { resp.Body.Close() }; t1 := time.Now(); resp2, err2 := http.Post("http://localhost:11434/api/tags", "application/json", nil); fmt.Println("localhost:", time.Since(t1), err2); if resp2 != nil { resp2.Body.Close() } }
